    constexpr int DATA_WIDTH = 1200, DATA_HEIGHT = 600;

    template<size_t N, size_t L>
    vector<uint8_t> DecompressRLE(const array<RLEBlock, N> &blocks, const array<uint8_t, L> &literals)
    {
        vector<uint8_t> output;

        for (const auto &block: blocks)
        {
            if (block.Type == RLEBlockType::Run)
            {
                output.insert(output.end(), block.Count, block.Value);
            } else
            {
                output.insert(output.end(), literals.begin() + block.Offset,
                              literals.begin() + block.Offset + block.Count);
            }
        }

        return output;
    }
